    {"id":"MPPSC-2012-028","paper_id":"MPPSC-2012-P1","exam":"MPPSC State Service Preliminary Examination","year":2012,"set_code":"A","question_number":28,"question_type":"single_correct",
     "language_variants":{"en":{"question_text":"The Equator does not pass through which of the following countries?","instructions":None,"options":[{"key":"A","text":"Kenya"},{"key":"B","text":"Mexico"},{"key":"C","text":"Indonesia"},{"key":"D","text":"Brazil"}]},
                        "hi":{"question_text":"भूमध्यरेखा निम्नलिखित में से किस देश से होकर **नहीं** गुजरती है ?","instructions":None,"options":[{"key":"A","text":"कीनिया (केन्या)"},{"key":"B","text":"मेक्सिको"},{"key":"C","text":"इंडोनेशिया"},{"key":"D","text":"ब्राजील"}]}},
     "supplied_answer":{"answer":["B"],"status":"supplied","source":"Source material (no official key); independently verified.","notes":"The Equator passes through: Ecuador, Colombia, Brazil, São Tomé and Príncipe, Gabon, Republic of Congo, DRC, Uganda, Kenya, Somalia, Indonesia, Maldives, Kiribati. Mexico is north of the Equator."},
     "answer_key_status":"supplied",
     "verified_answer":{"answer":["B"],"verified_by":"Pipeline independent verification","verified_at":"2026-11-02","evidence":[{"title":"Equator — countries crossed","citation":"Standard geography references / National Geographic","url":"https://education.nationalgeographic.org/resource/equator/"}],"status":"verified"},
     "explanation":{"language":"en","correct_reasoning":"The Equator (0° latitude) passes through several countries including Kenya (just north of the equator but the line passes through), Indonesia (Sumatra, Borneo, Sulawesi), and Brazil (Amazon region). Mexico lies entirely north of the Equator (its southernmost point is around 14°N). Therefore, Mexico is the country the Equator does not pass through.","option_explanations":[{"key":"A","text":"Kenya","is_correct":False,"reason":"The Equator passes through Kenya (near Mount Kenya and the town of Nanyuki)."},{"key":"B","text":"Mexico","is_correct":True,"reason":"Correct. Mexico is entirely north of the Equator; its southern border is around 14°N."},{"key":"C","text":"Indonesia","is_correct":False,"reason":"The Equator passes through several Indonesian islands including Sumatra, Borneo, and Sulawesi."},{"key":"D","text":"Brazil","is_correct":False,"reason":"The Equator crosses northern Brazil, passing through the Amazon rainforest and the states of Amapá, Pará, Roraima, and Amazonas."}],"key_concepts":["Equator — 0° latitude","Countries crossed: Ecuador, Colombia, Brazil, Gabon, DRC, Uganda, Kenya, Somalia, Indonesia, Maldives, Kiribati"],"revision_takeaways":["Equator does NOT pass through Mexico (north of equator)."],"sources":[{"title":"Equator (National Geographic Education)","citation":"National Geographic Society","url":"https://education.nationalgeographic.org/resource/equator/"}]},
     "subject":"Geography","topic":"World Geography","subtopic":"International boundaries",
     "dispute":None,"source_reference":{"file":"/tmp/arena-coding-uploads/MPPSC-Prelims-Exam-Paper-2012-Paper-I.md","page":11,"question_location":"Q28","note":"Both Hindi and English versions present."},
     "validation_status":"valid","validation_notes":["Unique ID MPPSC-2012-028.","No duplicate content detected.","Answer verified: B (Mexico — north of Equator)."]},
